import React from 'react';
import { motion } from 'framer-motion';

const testimonials = [
  {
    id: 1,
    name: "Dr. APJ Abdul Kalam",
    role: "Former President of India",
    image: "https://i.pravatar.cc/150?img=11",
    quote: "The students of CEC display an extraordinary capacity for innovation and futuristic thinking."
  },
  {
    id: 2,
    name: "Sarah Jenkins",
    role: "Director of Engineering, TechCorp",
    image: "https://i.pravatar.cc/150?img=5",
    quote: "The alumni we've hired from this institution have consistently pushed the boundaries of what's possible."
  },
  {
    id: 3,
    name: "David Chen",
    role: "Startup Founder",
    image: "https://i.pravatar.cc/150?img=12",
    quote: "Exceptional talent pool. The practical, future-ready skills taught here are transforming the industry."
  },
  {
    id: 4,
    name: "Dr. Maya Patel",
    role: "Lead Researcher, AI Institute",
    image: "https://i.pravatar.cc/150?img=9",
    quote: "A beacon of technological advancement. The campus environment perfectly nurtures out-of-the-box ideas."
  }
];

const Testimonial = () => {
  return (
    <section id="testimonials" className="py-20 relative overflow-hidden bg-slate-900 border-y border-slate-800">
      {/* Background glow effects */}
      <div className="absolute top-1/2 left-1/4 w-96 h-96 bg-cyan-500/20 rounded-full blur-[120px] -translate-y-1/2"></div>
      <div className="absolute top-1/2 right-1/4 w-96 h-96 bg-purple-500/20 rounded-full blur-[120px] -translate-y-1/2"></div>

      <div className="max-w-[95%] mx-auto px-4 lg:px-6 relative z-10">
        <div className="mb-14 text-center">
            <h2 className="text-[2.25rem] font-display font-bold text-white mb-4 tracking-wide uppercase">
                Voices of the <span className="text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 to-purple-400">Future</span>
            </h2>
            <div className="w-24 h-1 bg-gradient-to-r from-cyan-400 to-purple-400 mx-auto rounded-full"></div>
            <p className="mt-4 text-slate-300 max-w-2xl mx-auto font-body">
                Hear what industry leaders and visionaries have to say about our community.
            </p>
        </div>

        <div className="relative flex overflow-hidden group">
            {/* We duplicate the array to create an infinite scroll illusion */}
            <motion.div 
               className="flex space-x-6 min-w-max px-4 pb-8"
               animate={{ x: [0, -1200] }} /* Depending on element size, the scroll distance varies */
               transition={{ 
                 repeat: Infinity,
                 ease: "linear",
                 duration: 25
               }}
            >
                {[...testimonials, ...testimonials, ...testimonials].map((t, idx) => (
                    <div 
                        key={idx} 
                        className="w-[350px] sm:w-[400px] relative p-[1px] rounded-2xl bg-gradient-to-br from-white/10 to-transparent hover:from-cyan-400/50 hover:to-purple-500/50 transition-colors duration-500 cursor-pointer"
                    >
                        <div className="h-full w-full bg-slate-900/80 backdrop-blur-xl rounded-2xl p-8 flex flex-col justify-between shadow-[0_8px_32px_rgba(0,0,0,0.3)] hover:bg-slate-900/60 transition-colors duration-500">
                            <div>
                                <div className="text-cyan-400 text-5xl font-serif leading-none mb-2 opacity-70">"</div>
                                <p className="text-slate-300 leading-relaxed font-body mb-8">
                                    {t.quote}
                                </p>
                            </div>
                            <div className="flex items-center gap-4 mt-auto">
                                <div className="relative">
                                    <div className="absolute inset-0 bg-gradient-to-tr from-cyan-400 to-purple-500 rounded-full blur-sm opacity-50"></div>
                                    <img 
                                        src={t.image} 
                                        alt={t.name} 
                                        className="w-12 h-12 rounded-full object-cover border-2 border-slate-800 relative z-10"
                                        loading="lazy"
                                    />
                                </div>
                                <div>
                                    <h4 className="text-white font-bold tracking-wide text-sm">{t.name}</h4>
                                    <p className="text-cyan-400 text-[0.7rem] font-semibold uppercase tracking-wider">{t.role}</p>
                                </div>
                            </div>
                        </div>
                    </div>
                ))}
            </motion.div>

            {/* Fade overlays for smooth scrolling edges */}
            <div className="absolute inset-y-0 left-0 w-16 sm:w-32 bg-gradient-to-r from-slate-900 to-transparent z-20 pointer-events-none"></div>
            <div className="absolute inset-y-0 right-0 w-16 sm:w-32 bg-gradient-to-l from-slate-900 to-transparent z-20 pointer-events-none"></div>
        </div>
      </div>
    </section>
  );
};

export default Testimonial;
